package com.hospital.mes.qms.application;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.hospital.mes.audit.application.CurrentPlatformContext;
import com.hospital.mes.audit.idempotency.*;
import com.hospital.mes.audit.signature.SignatureMeaning;
import com.hospital.mes.common.exception.ResourceConflictException;
import com.hospital.mes.masterdata.application.*;
import com.hospital.mes.production.application.ProductionQueryService;
import com.hospital.mes.execution.application.ExecutionQueryService;
import com.hospital.mes.qms.infrastructure.*;
import org.springframework.stereotype.Service;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.transaction.annotation.*;
import java.util.*;
import java.math.BigDecimal;
import static com.hospital.mes.production.application.ProductionInput.*;
import static com.hospital.mes.qms.domain.IncomingRules.*;
import static com.hospital.mes.qms.infrastructure.IncomingStore.now;
@Service @ConditionalOnProperty(prefix="spring.datasource",name="url")
public class ProductionQualityService {
 public static final String SAMPLE="qms_sample",TEST="qms_production_test_instance",RESULT="qms_test_result_revision",REVIEW="qms_production_test_review",DEV="qms_deviation",CAPA="qms_capa",CAPAREVIEW="qms_capa_review";
 private final com.hospital.mes.equipment.application.EquipmentQueryService equipment; private final IncomingStore db; private final ProductionQueryService batches;private final ExecutionQueryService operations;private final MasterQueryService units;private final MasterMutation mutations;private final SignedRecordSupport signing;private final PlatformIdempotencyService keys;private final ObjectMapper json;
 public ProductionQualityService(com.hospital.mes.equipment.application.EquipmentQueryService equipment,IncomingStore db,ProductionQueryService batches,ExecutionQueryService operations,MasterQueryService units,MasterMutation mutations,SignedRecordSupport signing,PlatformIdempotencyService keys,ObjectMapper json){this.equipment=equipment;this.db=db;this.batches=batches;this.operations=operations;this.units=units;this.mutations=mutations;this.signing=signing;this.keys=keys;this.json=json;}
 private JsonNode parse(String s){try{return json.readTree(s);}catch(Exception e){throw new IllegalStateException("Corrupt quality evidence",e);}}
 private ProductionQueryService.BatchContext root(long org,long batch){var b=batches.lockBatch(org,batch);gate(!Set.of("QA_RELEASED","REJECTED").contains(b.status()),"QUALITY_FINAL_QA_FROZEN","Final QA requires controlled investigation path");return b;}
 private JsonNode plan(long org,long batch){var p=batches.batch(org,batch).snapshot().path("qualityPlan");gate(p.path("status").asText().equals("APPROVED"),"QUALITY_PLAN_REQUIRED","Actual dispatched approved quality plan required");gate(signing.valid(org,p.path("signatureId").asLong()),"QUALITY_PLAN_SIGNATURE_INVALID","Plan signature invalid");return p;}
 private SampleRow sample(long org,long id){var s=(SampleRow)db.get(SAMPLE,org,id);if(!"PRODUCTION".equals(s.getSampleScope()))throw new NoSuchElementException("Production sample not found");return s;}
 private ProductionTestInstanceRow test(long org,long id){return (ProductionTestInstanceRow)db.get(TEST,org,id);}
 private DeviationRow deviation(long org,long id){var d=(DeviationRow)db.get(DEV,org,id);if(!"PRODUCTION".equals(d.getInvestigationScope()))throw new NoSuchElementException("Production deviation not found");return d;}
 public boolean productionDeviation(String id){return productionDeviation(id,"qms:deviation:view");} public boolean productionDeviation(String id,String permission){var c=mutations.context(permission);return "PRODUCTION".equals(((DeviationRow)db.get(DEV,c.organizationId(),MasterMutation.id(id))).getInvestigationScope());}
 @Transactional(readOnly=true) public JsonNode get(String table,String id){var c=mutations.context(permission(table,"view"));var row=db.get(table,c.organizationId(),MasterMutation.id(id));if(table.equals(SAMPLE))sample(c.organizationId(),row.getId());if(table.equals(DEV))deviation(c.organizationId(),row.getId());return view(table,row);}
 @Transactional(readOnly=true) public ScopedStore.PageData<JsonNode> list(String table,int page,int size,Map<String,String> filters){var c=mutations.context(permission(table,"view"));if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid pagination");var rows=db.all(table,c.organizationId()).stream().filter(r->!table.equals(SAMPLE)||"PRODUCTION".equals(((SampleRow)r).getSampleScope())).filter(r->!table.equals(DEV)||"PRODUCTION".equals(((DeviationRow)r).getInvestigationScope())).filter(r->!filters.containsKey("status")||filters.get("status").equals(IncomingStore.text(r,"status"))).filter(r->!filters.containsKey("mainBatchId")||batchId(table,r)==MasterMutation.id(filters.get("mainBatchId"))).toList();return new ScopedStore.PageData<>(rows.stream().skip((long)page*size).limit(size).map(r->(JsonNode)view(table,r)).toList(),rows.size(),page,size);}
 private String permission(String table,String action){return table.equals(SAMPLE)?"qms:sample:"+action:table.equals(TEST)?"qms:test:"+action:table.equals(DEV)?"qms:deviation:"+action:"qms:capa:"+action;}
 private long batchId(String table,IncomingRow row){if(row instanceof SampleRow s)return s.getMainBatchId();if(row instanceof ProductionTestInstanceRow t)return sample(row.getOrgId(),t.getSampleId()).getMainBatchId();if(row instanceof DeviationRow d)return d.getMainBatchId();if(row instanceof CapaRow c)return deviation(row.getOrgId(),c.getSourceId()).getMainBatchId();throw new IllegalArgumentException("Unknown root");}
 private JsonNode command(String table,String permission,String action,String target,JsonNode body,String key,int status,java.util.function.Function<CurrentPlatformContext,IncomingRow> work){var c=mutations.context(permission);String reason=text(body,"reason",1000);String canonical;try{canonical=new org.erdtman.jcs.JsonCanonicalizer(json.writeValueAsBytes(Map.of("target",target,"body",body))).getEncodedString();}catch(Exception e){throw new IllegalArgumentException("Invalid command",e);}var k=keys.begin(new IdempotencyCommand(c.organizationId(),c.actorId(),action+":"+target,key,canonical));if(k.type()==IdempotencyDecisionType.REPLAY)return parse(k.responseJson());if(k.type()!=IdempotencyDecisionType.OWNER)throw new ResourceConflictException("IDEMPOTENCY_CONFLICT","Command key conflict");JsonNode before=null;if(!target.isEmpty()&&!action.endsWith("CREATE")){var existing=db.get(table,c.organizationId(),MasterMutation.id(target));root(c.organizationId(),batchId(table,existing));before=db.view(db.lock(table,c.organizationId(),existing.getId()));}IncomingRow row;try{row=work.apply(c);}catch(RuntimeException e){throw ScopedStore.translateConcurrency(e);}mutations.auditSnapshot(c,action,table,row.getId(),before,db.view(row),reason,key);var response=view(table,row);keys.complete(k.handle(),status,response.toString(),table,row.getId().toString());return parse(response.toString());}
 private void scope(JsonNode b){gate(text(b,"investigationScope",30).equals("PRODUCTION"),"QUALITY_SCOPE_REQUIRED","Production scope required");}
 /** Dedicated finished request producer; ordinary production sample creation remains IN_PROGRESS-only. */
 @Transactional(propagation=Propagation.MANDATORY) public SampleRow createFinishedSample(CurrentPlatformContext c,long batch,long lot,String sampleNo,String sampleType,BigDecimal quantity,long unit,String source){
  state(root(c.organizationId(),batch).status(),"PRODUCTION_COMPLETED");var p=plan(c.organizationId(),batch);gate(Objects.equals(lot,batches.qualityIdentity(c.organizationId(),batch).finishedLotId()),"SAMPLE_LOT_BATCH_MISMATCH","Finished sample must identify the actual batch lot");
  gate(Set.of("TEST_SAMPLE","RETENTION_SAMPLE","RETEST_SAMPLE","OTHER_APPROVED").contains(sampleType),"SAMPLE_TYPE_INVALID","Controlled sample type required");units.unit(c.organizationId(),unit);var row=new SampleRow();row.setSampleScope("PRODUCTION");row.setMainBatchId(batch);row.setMaterialLotId(lot);row.setSampleNo(sampleNo);row.setSampleType(sampleType);row.setQuantity(quantity);row.setUnitId(unit);row.setSourceRef(source);row.setProductionPlanId(p.path("id").asLong());row.setQcSpecificationVersionId(p.path("qcSpecificationVersionId").asLong());row.setStatus("COLLECTED");row.setSampledAt(now());db.insert(SAMPLE,row,c.organizationId(),c.actorId());return row;
 }
 @Transactional public JsonNode createSample(JsonNode b,String key){fields(b,"mainBatchId","sampleNo","sampleType","materialLotId","quantity","unitId","sourceRef","reason","investigationScope");scope(b);return command(SAMPLE,"qms:sample:create","PRODUCTION_SAMPLE_CREATE","",b,key,201,c->{long batch=id(b,"mainBatchId");state(root(c.organizationId(),batch).status(),"IN_PROGRESS");var p=plan(c.organizationId(),batch);Long lot=optionalId(b,"materialLotId");if(lot!=null)gate(Objects.equals(lot,batches.qualityIdentity(c.organizationId(),batch).finishedLotId()),"SAMPLE_LOT_BATCH_MISMATCH","Sample lot must belong to batch");units.unit(c.organizationId(),id(b,"unitId"));var s=new SampleRow();s.setSampleScope("PRODUCTION");s.setSampleNo(text(b,"sampleNo",80));s.setMainBatchId(batch);s.setProductionPlanId(p.path("id").asLong());s.setQcSpecificationVersionId(p.path("qcSpecificationVersionId").asLong());s.setMaterialLotId(lot);s.setSampleType(text(b,"sampleType",30));gate(Set.of("TEST_SAMPLE","RETENTION_SAMPLE","RETEST_SAMPLE","OTHER_APPROVED").contains(s.getSampleType()),"SAMPLE_TYPE_INVALID","Invalid sample type");s.setQuantity(com.hospital.mes.qms.domain.IncomingRules.quantity(text(b,"quantity",50)));s.setUnitId(id(b,"unitId"));s.setSourceRef(text(b,"sourceRef",100));s.setStatus("COLLECTED");s.setSampledAt(now());db.insert(SAMPLE,s,c.organizationId(),c.actorId());return s;});}
 @Transactional public JsonNode receiveSample(String target,JsonNode b,String header,String key){fields(b,"versionNo","reason");long v=ProductionQualityPlanService.expected(b,header);return command(SAMPLE,"qms:sample:receive","PRODUCTION_SAMPLE_RECEIVE",target,b,key,200,c->{var found=sample(c.organizationId(),MasterMutation.id(target));root(c.organizationId(),found.getMainBatchId());var s=(SampleRow)db.lock(SAMPLE,c.organizationId(),found.getId());version(s.getVersionNo(),v);state(s.getStatus(),"COLLECTED");s.setStatus("RECEIVED");s.setReceivedBy(c.actorId());s.setReceivedAt(now());db.update(SAMPLE,s,v,c.actorId(),"status","receivedBy","receivedAt");return s;});}
 @Transactional public JsonNode createTest(JsonNode b,String key){fields(b,"sampleId","specificationItemId","instrumentId","reason");return command(TEST,"qms:test:record","PRODUCTION_TEST_CREATE","",b,key,201,c->{var s=sample(c.organizationId(),id(b,"sampleId"));root(c.organizationId(),s.getMainBatchId());s=(SampleRow)db.lock(SAMPLE,c.organizationId(),s.getId());state(s.getStatus(),"RECEIVED","IN_TEST");var p=plan(c.organizationId(),s.getMainBatchId());JsonNode item=null;for(var i:p.path("specification").path("items"))if(i.path("specificationItemId").asLong()==id(b,"specificationItemId"))item=i;gate(item!=null,"QUALITY_ITEM_MISMATCH","Item absent from frozen plan");for(var r:db.rows(TEST,c.organizationId(),"sampleId",s.getId()))gate(!Objects.equals(((ProductionTestInstanceRow)r).getQcSpecificationItemId(),id(b,"specificationItemId")),"TEST_ALREADY_EXISTS","Use controlled retest");var t=new ProductionTestInstanceRow();t.setSampleId(s.getId());t.setProductionPlanId(s.getProductionPlanId());t.setQcSpecificationItemId(id(b,"specificationItemId"));ObjectNode frozen=json.createObjectNode();frozen.set("item",item);frozen.put("specificationVersionId",s.getQcSpecificationVersionId().toString());frozen.put("specificationHash",p.path("specification").path("contentHash").asText());t.setSpecificationSnapshotJson(frozen.toString());t.setTestCode(item.path("itemCode").asText());t.setAttemptNo(1);t.setStatus("READY");t.setInstrumentId(optionalId(b,"instrumentId"));if(t.getInstrumentId()!=null)equipment.requireUsable(c.organizationId(),t.getInstrumentId(),java.time.Instant.now());db.insert(TEST,t,c.organizationId(),c.actorId());s.setStatus("IN_TEST");db.update(SAMPLE,s,s.getVersionNo(),c.actorId(),"status");return t;});}
 @Transactional public JsonNode result(String target,boolean correction,JsonNode b,String header,String key){fields(b,"versionNo","reason","signature","previousRevisionId","resultNumeric","resultText");long v=ProductionQualityPlanService.expected(b,header);return command(TEST,"qms:test:record",correction?"PRODUCTION_RESULT_REVISE":"PRODUCTION_RESULT_RECORD",target,b,key,200,c->{var found=test(c.organizationId(),MasterMutation.id(target));root(c.organizationId(),sample(c.organizationId(),found.getSampleId()).getMainBatchId());var t=(ProductionTestInstanceRow)db.lock(TEST,c.organizationId(),found.getId());version(t.getVersionNo(),v);state(t.getStatus(),correction?"COMPLETED":"READY");if(t.getInstrumentId()!=null)equipment.requireUsable(c.organizationId(),t.getInstrumentId(),java.time.Instant.now());var item=parse(t.getSpecificationSnapshotJson()).path("item");var r=new TestResultRevisionRow();r.setProductionTestInstanceId(t.getId());r.setSampleId(t.getSampleId());r.setTestCode(t.getTestCode());r.setRevisionNo(1);if(item.path("resultType").asText().equals("NUMERIC")){gate(!b.hasNonNull("resultText"),"RESULT_TYPE_INVALID","Numeric item requires numeric result");var value=decimal(text(b,"resultNumeric",50));r.setResultNumeric(value);r.setResultUnitId(item.hasNonNull("unitId")?item.path("unitId").asLong():null);r.setResultConclusion(numeric(value,item.hasNonNull("lowerLimit")?new BigDecimal(item.path("lowerLimit").asText()):null,item.hasNonNull("upperLimit")?new BigDecimal(item.path("upperLimit").asText()):null));}else{gate(!b.hasNonNull("resultNumeric"),"RESULT_TYPE_INVALID","Text item requires text result");r.setResultText(text(b,"resultText",1000));r.setResultConclusion(r.getResultText().equals(item.path("textAcceptanceCriteria").asText())?"PASS":"FAIL");}if(correction){gate(Objects.equals(optionalId(b,"previousRevisionId"),t.getCurrentResultRevisionId()),"RESULT_LINEAGE_MISMATCH","Exact predecessor required");var old=(TestResultRevisionRow)db.get(RESULT,c.organizationId(),t.getCurrentResultRevisionId());com.hospital.mes.qms.domain.IncomingRules.correction(old.getResultConclusion(),r.getResultConclusion());gate(db.rows(REVIEW,c.organizationId(),"resultRevisionId",old.getId()).isEmpty(),"RESULT_REVIEW_FROZEN","Reviewed result requires controlled investigation");r.setPreviousRevisionId(old.getId());r.setRevisionNo(old.getRevisionNo()+1);}else gate(!b.hasNonNull("previousRevisionId"),"RESULT_LINEAGE_MISMATCH","Original result has no predecessor");r.setReasonForChange(text(b,"reason",1000));r.setRecordedBy(c.actorId());r.setRecordedAt(now());var e=signing.sign(c,"PRODUCTION_TEST_RESULT",target+":"+v,v,SignatureMeaning.VERIFY,r,b.get("signature"),key,List.of("ProductionTest:"+t.getId()));r.setSignatureId(e.id());r.setSignatureEvidenceJson(e.envelope());db.insert(RESULT,r,c.organizationId(),c.actorId());t.setCurrentResultRevisionId(r.getId());t.setPerformedBy(c.actorId());t.setStatus("COMPLETED");db.update(TEST,t,v,c.actorId(),"currentResultRevisionId","performedBy","status");if(r.getResultConclusion().equals("FAIL"))autoOos(c,t,r);completeSample(c,t);return t;});}
 private BigDecimal decimal(String s){if(!s.matches("-?(?:0|[1-9][0-9]{0,15})(?:\\.[0-9]{1,8})?"))throw new IllegalArgumentException("Decimal(24,8) required");return new BigDecimal(s);}
 private void completeSample(CurrentPlatformContext c,ProductionTestInstanceRow t){var s=sample(c.organizationId(),t.getSampleId());boolean complete=true;for(var i:plan(c.organizationId(),s.getMainBatchId()).path("specification").path("items"))if(i.path("required").asBoolean()){boolean done=false;for(var raw:db.rows(TEST,c.organizationId(),"sampleId",s.getId())){var actual=(ProductionTestInstanceRow)raw;if(actual.getQcSpecificationItemId()==i.path("specificationItemId").asLong()&&actual.getStatus().equals("COMPLETED"))done=true;}complete&=done;}if(complete){s=(SampleRow)db.lock(SAMPLE,c.organizationId(),s.getId());s.setStatus("TEST_COMPLETED");db.update(SAMPLE,s,s.getVersionNo(),c.actorId(),"status");}}
 private void autoOos(CurrentPlatformContext c,ProductionTestInstanceRow t,TestResultRevisionRow r){var d=new DeviationRow();d.setMainBatchId(sample(c.organizationId(),t.getSampleId()).getMainBatchId());d.setInvestigationScope("PRODUCTION");d.setInvestigationKind("OOS");d.setDeviationNo("POOS-"+r.getId());d.setSeverity("MAJOR");d.setStatus("OPEN");d.setDescription("Original production test FAIL "+t.getTestCode());d.setProductionTestInstanceId(t.getId());d.setOriginalResultRevisionId(r.getId());db.insert(DEV,d,c.organizationId(),c.actorId());mutations.auditSnapshot(c,"PRODUCTION_OOS_OPEN",DEV,d.getId(),null,db.view(d),"Original FAIL",null);}
 @Transactional public JsonNode review(String target,JsonNode b,String header,String key){fields(b,"versionNo","reason","signature","resultRevisionId","disposition");long v=ProductionQualityPlanService.expected(b,header);return command(TEST,"qms:test:review","PRODUCTION_RESULT_REVIEW",target,b,key,200,c->{var found=test(c.organizationId(),MasterMutation.id(target));root(c.organizationId(),sample(c.organizationId(),found.getSampleId()).getMainBatchId());var t=(ProductionTestInstanceRow)db.lock(TEST,c.organizationId(),found.getId());version(t.getVersionNo(),v);state(t.getStatus(),"COMPLETED");gate(Objects.equals(t.getCurrentResultRevisionId(),id(b,"resultRevisionId")),"RESULT_LINEAGE_MISMATCH","Current result required");var r=(TestResultRevisionRow)db.get(RESULT,c.organizationId(),id(b,"resultRevisionId"));gate(!Objects.equals(r.getRecordedBy(),c.actorId()),"INDEPENDENT_REVIEW_REQUIRED","Recorder cannot review");gate(signing.valid(c.organizationId(),r.getSignatureId()),"RESULT_SIGNATURE_INVALID","Result signature invalid");gate(db.rows(REVIEW,c.organizationId(),"resultRevisionId",r.getId()).isEmpty(),"RESULT_ALREADY_REVIEWED","Review immutable");var review=new ProductionTestReviewRow();review.setResultRevisionId(r.getId());review.setDisposition(text(b,"disposition",30));gate(Set.of("CONFIRMED","INVALIDATED").contains(review.getDisposition()),"RESULT_REVIEW_INVALID","Invalid disposition");review.setReason(text(b,"reason",1000));review.setReviewedBy(c.actorId());review.setReviewedAt(now());var e=signing.sign(c,"PRODUCTION_TEST_REVIEW",target+":"+v,v,SignatureMeaning.VERIFY,review,b.get("signature"),key,List.of("TestResultRevision:"+r.getId()));review.setSignatureId(e.id());review.setSignatureEvidenceJson(e.envelope());db.insert(REVIEW,review,c.organizationId(),c.actorId());db.update(TEST,t,v,c.actorId());return t;});}
 @Transactional public JsonNode retest(String target,JsonNode b,String header,String key){fields(b,"versionNo","reason","investigationId");long v=ProductionQualityPlanService.expected(b,header);return command(TEST,"qms:test:retest","PRODUCTION_RETEST",target,b,key,200,c->{var old=test(c.organizationId(),MasterMutation.id(target));root(c.organizationId(),sample(c.organizationId(),old.getSampleId()).getMainBatchId());old=(ProductionTestInstanceRow)db.lock(TEST,c.organizationId(),old.getId());version(old.getVersionNo(),v);var d=deviation(c.organizationId(),id(b,"investigationId"));d=(DeviationRow)db.lock(DEV,c.organizationId(),d.getId());gate(Objects.equals(d.getMainBatchId(),sample(c.organizationId(),old.getSampleId()).getMainBatchId()),"RETEST_BATCH_MISMATCH","Investigation and test must belong to the same batch");gate(d.getStatus().equals("DECIDED")&&d.getDecisionCode().equals("AUTHORIZE_RETEST")&&Objects.equals(d.getProductionTestInstanceId(),old.getId())&&"INVALID".equals(d.getOriginalResultDisposition())&&signing.valid(c.organizationId(),d.getDecisionSignatureId()),"RETEST_NOT_AUTHORIZED","Exact signed invalid-original investigation required");var origin=(TestResultRevisionRow)db.get(RESULT,c.organizationId(),d.getOriginalResultRevisionId());var originReview=reviewOf(c.organizationId(),origin.getId());gate(Objects.equals(origin.getProductionTestInstanceId(),old.getId())&&originReview!=null&&"INVALIDATED".equals(originReview.getDisposition())&&signing.valid(c.organizationId(),origin.getSignatureId())&&signing.valid(c.organizationId(),originReview.getSignatureId()),"RETEST_SOURCE_MISMATCH","Exact signed invalidated original source required");var attempts=db.rows(TEST,c.organizationId(),"approvedInvestigationId",d.getId());gate(attempts.size()<d.getAuthorizedRetestCount(),"RETEST_QUOTA_EXHAUSTED","Retest quota exhausted");var t=new ProductionTestInstanceRow();t.setSampleId(old.getSampleId());t.setProductionPlanId(old.getProductionPlanId());t.setQcSpecificationItemId(old.getQcSpecificationItemId());t.setSpecificationSnapshotJson(old.getSpecificationSnapshotJson());t.setTestCode(old.getTestCode());int nextAttempt=1;for(var existing:db.rows(TEST,c.organizationId(),"sampleId",old.getSampleId())){var same=(ProductionTestInstanceRow)existing;if(Objects.equals(same.getQcSpecificationItemId(),old.getQcSpecificationItemId()))nextAttempt=Math.max(nextAttempt,same.getAttemptNo()+1);}t.setAttemptNo(nextAttempt);t.setPreviousInstanceId(old.getId());t.setApprovedInvestigationId(d.getId());t.setInstrumentId(old.getInstrumentId());t.setStatus("READY");db.insert(TEST,t,c.organizationId(),c.actorId());db.update(TEST,old,v,c.actorId());return t;});}
 @Transactional public JsonNode createDeviation(JsonNode b,String key){fields(b,"investigationScope","mainBatchId","operationExecutionId","investigationKind","severity","description","productionTestInstanceId","originalResultRevisionId","reason");scope(b);return command(DEV,"qms:deviation:create","PRODUCTION_DEVIATION_CREATE","",b,key,201,c->{long batch=id(b,"mainBatchId");root(c.organizationId(),batch);Long op=optionalId(b,"operationExecutionId");if(op!=null)gate(operations.operation(c.organizationId(),op).mainBatchId()==batch,"DEVIATION_OPERATION_MISMATCH","Operation belongs to another batch");var d=new DeviationRow();d.setMainBatchId(batch);d.setOperationExecutionId(op);d.setInvestigationScope("PRODUCTION");d.setInvestigationKind(text(b,"investigationKind",30));gate(Set.of("DEVIATION","OOS","OOT").contains(d.getInvestigationKind()),"DEVIATION_KIND_INVALID","Invalid kind");d.setSeverity(text(b,"severity",30));gate(Set.of("MINOR","MAJOR","CRITICAL").contains(d.getSeverity()),"DEVIATION_SEVERITY_INVALID","Invalid severity");d.setDescription(text(b,"description",1000));d.setProductionTestInstanceId(optionalId(b,"productionTestInstanceId"));d.setOriginalResultRevisionId(optionalId(b,"originalResultRevisionId"));if(!d.getInvestigationKind().equals("DEVIATION")||d.getProductionTestInstanceId()!=null||d.getOriginalResultRevisionId()!=null){gate(d.getProductionTestInstanceId()!=null&&d.getOriginalResultRevisionId()!=null,"ORIGINAL_RESULT_REQUIRED","OOS/OOT require original result");var t=test(c.organizationId(),d.getProductionTestInstanceId());var r=(TestResultRevisionRow)db.get(RESULT,c.organizationId(),d.getOriginalResultRevisionId());gate(sample(c.organizationId(),t.getSampleId()).getMainBatchId()==batch&&Objects.equals(r.getProductionTestInstanceId(),t.getId())&&r.getRevisionNo()==1,"RESULT_LINEAGE_MISMATCH","Original scoped result required");if(d.getInvestigationKind().equals("OOS")){gate(r.getResultConclusion().equals("FAIL"),"OOS_FAIL_REQUIRED","OOS requires original FAIL");gate(db.rows(DEV,c.organizationId(),"originalResultRevisionId",r.getId()).stream().noneMatch(x->"OOS".equals(((DeviationRow)x).getInvestigationKind())),"OOS_ALREADY_EXISTS","Original OOS already exists");}}d.setStatus("OPEN");d.setDeviationNo("PDEV-"+UUID.randomUUID());db.insert(DEV,d,c.organizationId(),c.actorId());return d;});}
 @Transactional public JsonNode deviationAction(String target,String action,JsonNode b,String header,String key){switch(action){case "update"->fields(b,"versionNo","reason","investigationScope","description");case "investigate"->fields(b,"versionNo","reason","investigationScope","investigationSummary");case "decide"->fields(b,"versionNo","reason","signature","investigationScope","decisionCode","disposition","authorizedRetestCount","originalResultDisposition");case "close"->fields(b,"versionNo","reason","signature","investigationScope","selectedResultRevisionId");default->throw new IllegalArgumentException("Invalid command");}scope(b);long v=ProductionQualityPlanService.expected(b,header);return command(DEV,"qms:deviation:"+(action.equals("update")?"update":action),"PRODUCTION_DEVIATION_"+action.toUpperCase(Locale.ROOT),target,b,key,200,c->{var found=deviation(c.organizationId(),MasterMutation.id(target));root(c.organizationId(),found.getMainBatchId());var d=(DeviationRow)db.lock(DEV,c.organizationId(),found.getId());version(d.getVersionNo(),v);
 if(action.equals("update")){state(d.getStatus(),"OPEN");d.setDescription(text(b,"description",1000));db.update(DEV,d,v,c.actorId(),"description");}
 else if(action.equals("investigate")){state(d.getStatus(),"OPEN","INVESTIGATING");d.setInvestigationSummary(text(b,"investigationSummary",1000));d.setStatus("INVESTIGATING");db.update(DEV,d,v,c.actorId(),"investigationSummary","status");}
 else if(action.equals("decide")){state(d.getStatus(),"INVESTIGATING");gate(!Objects.equals(c.actorId(),d.getCreatedBy())&&!Objects.equals(c.actorId(),d.getUpdatedBy()),"INDEPENDENT_REVIEW_REQUIRED","Author/investigator cannot decide");d.setDecisionCode(text(b,"decisionCode",40));gate(Set.of("REJECT","AUTHORIZE_RETEST","ACCEPT_WITH_JUSTIFICATION").contains(d.getDecisionCode()),"DEVIATION_DECISION_INVALID","Invalid decision");d.setDisposition(text(b,"disposition",1000));d.setOriginalResultDisposition(b.hasNonNull("originalResultDisposition")?text(b,"originalResultDisposition",30):null);if(d.getOriginalResultRevisionId()!=null){var r=(TestResultRevisionRow)db.get(RESULT,c.organizationId(),d.getOriginalResultRevisionId());gate(!Objects.equals(c.actorId(),r.getRecordedBy()),"INDEPENDENT_REVIEW_REQUIRED","Original recorder cannot decide investigation");var rv=reviewOf(c.organizationId(),r.getId());gate(rv!=null&&signing.valid(c.organizationId(),rv.getSignatureId()),"ORIGINAL_REVIEW_REQUIRED","Original result requires independent signed review");gate(Objects.equals(d.getOriginalResultDisposition(),rv.getDisposition().equals("INVALIDATED")?"INVALID":"VALID"),"ORIGINAL_DISPOSITION_MISMATCH","Decision must match immutable review");}if(d.getDecisionCode().equals("AUTHORIZE_RETEST")){gate("INVALID".equals(d.getOriginalResultDisposition())&&d.getProductionTestInstanceId()!=null,"RETEST_ORIGINAL_INVALID_REQUIRED","Retest needs invalid original");gate(b.path("authorizedRetestCount").isIntegralNumber()&&b.path("authorizedRetestCount").asInt()>0&&b.path("authorizedRetestCount").asInt()<=10,"RETEST_QUOTA_INVALID","Positive quota <=10 required");d.setAuthorizedRetestCount(b.path("authorizedRetestCount").asInt());}else gate(!b.hasNonNull("authorizedRetestCount"),"RETEST_QUOTA_INVALID","Quota belongs only to retest");d.setDecidedBy(c.actorId());d.setDecidedAt(now());d.setStatus("DECIDED");var e=signing.sign(c,"PRODUCTION_DEVIATION",target+":"+v,v,SignatureMeaning.APPROVE,d,b.get("signature"),key,List.of("MainBatch:"+d.getMainBatchId()));d.setDecisionSignatureId(e.id());d.setDecisionSignatureEvidenceJson(e.envelope());db.update(DEV,d,v,c.actorId(),"decisionCode","disposition","originalResultDisposition","authorizedRetestCount","decidedBy","decidedAt","status","decisionSignatureId","decisionSignatureEvidenceJson");}
 else{state(d.getStatus(),"DECIDED");gate(!Objects.equals(c.actorId(),d.getCreatedBy())&&!Objects.equals(c.actorId(),d.getDecidedBy()),"INDEPENDENT_REVIEW_REQUIRED","Closure requires independent reviewer");gate(signing.valid(c.organizationId(),d.getDecisionSignatureId()),"DEVIATION_SIGNATURE_INVALID","Decision signature invalid");gate(capasComplete(c.organizationId(),d.getId()),"CAPA_UNRESOLVED","All CAPA must be verified");Long selected=optionalId(b,"selectedResultRevisionId");if(d.getOriginalResultRevisionId()!=null){gate(selected!=null,"SELECTED_RESULT_REQUIRED","Reviewed result required");var r=(TestResultRevisionRow)db.get(RESULT,c.organizationId(),selected);var t=test(c.organizationId(),r.getProductionTestInstanceId());gate(Objects.equals(t.getCurrentResultRevisionId(),r.getId()),"RESULT_LINEAGE_MISMATCH","Current result required");var rv=reviewOf(c.organizationId(),r.getId());gate(rv!=null&&rv.getDisposition().equals("CONFIRMED")&&signing.valid(c.organizationId(),rv.getSignatureId())&&signing.valid(c.organizationId(),r.getSignatureId()),"RESULT_REVIEW_REQUIRED","Valid independent result review required");if(d.getDecisionCode().equals("AUTHORIZE_RETEST")){var retests=db.rows(TEST,c.organizationId(),"approvedInvestigationId",d.getId());gate(retests.size()==d.getAuthorizedRetestCount()&&retests.stream().allMatch(x->reviewedRetest(c.organizationId(),(ProductionTestInstanceRow)x))&&Objects.equals(t.getApprovedInvestigationId(),d.getId())&&r.getResultConclusion().equals("PASS"),"RETEST_UNRESOLVED","Full quota and passing authorized retest required");}else gate(Objects.equals(selected,d.getOriginalResultRevisionId()),"RESULT_LINEAGE_MISMATCH","Exact original result required");}else gate(selected==null,"RESULT_LINEAGE_MISMATCH","Narrative deviation has no result");d.setSelectedResultRevisionId(selected);d.setCloseReason(text(b,"reason",1000));d.setClosedBy(c.actorId());d.setClosedAt(now());d.setStatus("CLOSED");var e=signing.sign(c,"PRODUCTION_DEVIATION",target+":"+v,v,SignatureMeaning.VERIFY,d,b.get("signature"),key,List.of("MainBatch:"+d.getMainBatchId()));d.setCloseSignatureId(e.id());d.setCloseSignatureEvidenceJson(e.envelope());db.update(DEV,d,v,c.actorId(),"selectedResultRevisionId","closeReason","closedBy","closedAt","status","closeSignatureId","closeSignatureEvidenceJson");}return d;});}
 @Transactional public JsonNode createCapa(String target,JsonNode b,String key){fields(b,"capaNo","actionText","reason");return command(CAPA,"qms:capa:create","PRODUCTION_CAPA_CREATE",target,b,key,201,c->{var d=deviation(c.organizationId(),MasterMutation.id(target));root(c.organizationId(),d.getMainBatchId());d=(DeviationRow)db.lock(DEV,c.organizationId(),d.getId());state(d.getStatus(),"OPEN","INVESTIGATING","DECIDED");var r=new CapaRow();r.setCapaNo(text(b,"capaNo",80));r.setActionText(text(b,"actionText",1000));r.setSourceType("PRODUCTION_DEVIATION");r.setSourceId(d.getId());r.setStatus("OPEN");db.insert(CAPA,r,c.organizationId(),c.actorId());return r;});}
 @Transactional(readOnly=true) public ScopedStore.PageData<JsonNode> capas(String target,int page,int size){var c=mutations.context("qms:capa:view");var d=deviation(c.organizationId(),MasterMutation.id(target));if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid pagination");var rows=db.rows(CAPA,c.organizationId(),"sourceId",d.getId());return new ScopedStore.PageData<>(rows.stream().skip((long)page*size).limit(size).map(r->(JsonNode)view(CAPA,r)).toList(),rows.size(),page,size);}
 @Transactional public JsonNode capaAction(String target,String action,JsonNode b,String header,String key){if(action.equals("start"))fields(b,"versionNo","reason");else if(action.equals("complete"))fields(b,"versionNo","reason","completionText");else if(action.equals("verify"))fields(b,"versionNo","reason","signature","decision");else throw new IllegalArgumentException("Invalid action");long v=ProductionQualityPlanService.expected(b,header);return command(CAPA,"qms:capa:"+(action.equals("verify")?"verify":"update"),"PRODUCTION_CAPA_"+action.toUpperCase(Locale.ROOT),target,b,key,200,c->{var found=(CapaRow)db.get(CAPA,c.organizationId(),MasterMutation.id(target));root(c.organizationId(),deviation(c.organizationId(),found.getSourceId()).getMainBatchId());var r=(CapaRow)db.lock(CAPA,c.organizationId(),found.getId());version(r.getVersionNo(),v);if(action.equals("start")){state(r.getStatus(),"OPEN");r.setStatus("IN_PROGRESS");db.update(CAPA,r,v,c.actorId(),"status");}else if(action.equals("complete")){state(r.getStatus(),"IN_PROGRESS");r.setStatus("COMPLETED");r.setCompletionText(text(b,"completionText",1000));r.setCompletedBy(c.actorId());r.setCompletedAt(now());db.update(CAPA,r,v,c.actorId(),"status","completionText","completedBy","completedAt");}else{state(r.getStatus(),"COMPLETED","VERIFIED");gate(!Objects.equals(c.actorId(),r.getCreatedBy())&&!Objects.equals(c.actorId(),r.getCompletedBy()),"INDEPENDENT_REVIEW_REQUIRED","CAPA author/completer cannot verify");var review=new CapaReviewRow();review.setCapaId(r.getId());review.setReviewNo(db.rows(CAPAREVIEW,c.organizationId(),"capaId",r.getId()).size()+1);review.setDecision(text(b,"decision",30));gate(Set.of("VERIFIED","REOPEN").contains(review.getDecision()),"CAPA_REVIEW_INVALID","Invalid decision");if(r.getStatus().equals("VERIFIED"))gate(review.getDecision().equals("REOPEN"),"CAPA_REVIEW_INVALID","Verified CAPA can only reopen");review.setReason(text(b,"reason",1000));review.setReviewedBy(c.actorId());review.setReviewedAt(now());var e=signing.sign(c,"PRODUCTION_CAPA",target+":"+v,v,SignatureMeaning.VERIFY,review,b.get("signature"),key,List.of("Deviation:"+r.getSourceId()));review.setSignatureId(e.id());review.setSignatureEvidenceJson(e.envelope());db.insert(CAPAREVIEW,review,c.organizationId(),c.actorId());r.setStatus(review.getDecision().equals("VERIFIED")?"VERIFIED":"IN_PROGRESS");db.update(CAPA,r,v,c.actorId(),"status");}return r;});}
 private boolean reviewedRetest(long org,ProductionTestInstanceRow t){if(!"COMPLETED".equals(t.getStatus())||t.getCurrentResultRevisionId()==null)return false;var r=(TestResultRevisionRow)db.get(RESULT,org,t.getCurrentResultRevisionId());var rv=reviewOf(org,r.getId());return Objects.equals(r.getProductionTestInstanceId(),t.getId())&&rv!=null&&signing.valid(org,r.getSignatureId())&&signing.valid(org,rv.getSignatureId())&&!Objects.equals(rv.getReviewedBy(),r.getRecordedBy());}
 private ProductionTestReviewRow reviewOf(long org,long result){var r=db.rows(REVIEW,org,"resultRevisionId",result);return r.isEmpty()?null:(ProductionTestReviewRow)r.getFirst();}
 private boolean capasComplete(long org,long dev){for(var raw:db.rows(CAPA,org,"sourceId",dev)){var c=(CapaRow)raw;if(!c.getStatus().equals("VERIFIED"))return false;var reviews=db.rows(CAPAREVIEW,org,"capaId",c.getId());if(reviews.isEmpty())return false;var r=(CapaReviewRow)reviews.getLast();if(!r.getDecision().equals("VERIFIED")||!signing.valid(org,r.getSignatureId()))return false;}return true;}
 /** Caller holds the batch root lock. qa=false checks critical findings for operation/batch completion. */
 @Transactional(propagation=Propagation.MANDATORY) public List<String> blockingCodes(long org,long batch,boolean qa){batches.lockBatch(org,batch);Set<String> codes=new LinkedHashSet<>();var deviations=db.lockedRows(DEV,org,"mainBatchId",batch);for(var raw:deviations){var d=(DeviationRow)raw;if(!"PRODUCTION".equals(d.getInvestigationScope()))continue;boolean closed="CLOSED".equals(d.getStatus())&&signing.valid(org,d.getCloseSignatureId())&&capasComplete(org,d.getId());if(d.getSeverity().equals("CRITICAL")&&!closed)codes.add("PRODUCTION_CRITICAL_UNRESOLVED");if(qa){if("REJECT".equals(d.getDecisionCode()))codes.add("PRODUCTION_DEVIATION_REJECTED");if(d.getInvestigationKind().equals("OOS")&&"VALID".equals(d.getOriginalResultDisposition()))codes.add("PRODUCTION_QC_ORIGINAL_FAIL");if(d.getInvestigationKind().equals("OOS")&&!closed)codes.add("PRODUCTION_OOS_UNRESOLVED");if(!closed&&!(d.getSeverity().equals("CRITICAL")?false:"DECIDED".equals(d.getStatus())&&"ACCEPT_WITH_JUSTIFICATION".equals(d.getDecisionCode())&&signing.valid(org,d.getDecisionSignatureId())&&capasComplete(org,d.getId())))codes.add("PRODUCTION_DEVIATION_UNRESOLVED");if(!capasComplete(org,d.getId()))codes.add("PRODUCTION_CAPA_UNRESOLVED");}}
 if(qa){JsonNode p=batches.batch(org,batch).snapshot().path("qualityPlan");if(!p.path("status").asText().equals("APPROVED"))codes.add("QUALITY_PLAN_REQUIRED");else for(var item:p.path("specification").path("items"))if(item.path("required").asBoolean()){boolean pass=false;for(var sr:db.rows(SAMPLE,org,"mainBatchId",batch)){var s=(SampleRow)sr;if(!"PRODUCTION".equals(s.getSampleScope())||!Objects.equals(s.getProductionPlanId(),p.path("id").asLong()))continue;for(var tr:db.rows(TEST,org,"sampleId",s.getId())){var t=(ProductionTestInstanceRow)tr;if(t.getQcSpecificationItemId()!=item.path("specificationItemId").asLong()||t.getCurrentResultRevisionId()==null)continue;var r=(TestResultRevisionRow)db.get(RESULT,org,t.getCurrentResultRevisionId());var rv=reviewOf(org,r.getId());boolean valid=r.getResultConclusion().equals("PASS")&&rv!=null&&rv.getDisposition().equals("CONFIRMED")&&signing.valid(org,r.getSignatureId())&&signing.valid(org,rv.getSignatureId());if(valid&&t.getApprovedInvestigationId()!=null){var d=deviation(org,t.getApprovedInvestigationId());valid="CLOSED".equals(d.getStatus())&&Objects.equals(d.getSelectedResultRevisionId(),r.getId())&&signing.valid(org,d.getCloseSignatureId());}pass|=valid;}}if(!pass)codes.add("PRODUCTION_QC_REQUIRED_RESULT");}}return List.copyOf(codes);}
 @Transactional(readOnly=true) public JsonNode evidence(long org,long batch){batches.batch(org,batch);var n=json.createObjectNode();var samples=n.putArray("samples");var tests=n.putArray("tests");var deviations=n.putArray("deviations");for(var s:db.rows(SAMPLE,org,"mainBatchId",batch))if("PRODUCTION".equals(((SampleRow)s).getSampleScope())){samples.add(view(SAMPLE,s));for(var t:db.rows(TEST,org,"sampleId",s.getId()))tests.add(view(TEST,t));}for(var d:db.rows(DEV,org,"mainBatchId",batch))if("PRODUCTION".equals(((DeviationRow)d).getInvestigationScope()))deviations.add(view(DEV,d));return n;}
 private ObjectNode view(String table,IncomingRow row){var n=db.view(row);n.remove(List.of("signatureEvidence","decisionSignatureEvidence","closeSignatureEvidence","disposalSignatureEvidence"));var a=n.putArray("allowedActions");boolean frozen=Set.of("QA_RELEASED","REJECTED").contains(batches.batch(row.getOrgId(),batchId(table,row)).status());if(row instanceof SampleRow s){n.retain("id","orgId","createdBy","createdAt","updatedBy","updatedAt","mainBatchId","productionPlanId","qcSpecificationVersionId","sampleNo","sampleScope","sampleType","materialLotId","quantity","unitId","sourceRef","status","sampledAt","receivedBy","receivedAt","versionNo","allowedActions");if(!frozen&&s.getStatus().equals("COLLECTED"))a.add("RECEIVE");}else if(row instanceof ProductionTestInstanceRow t){var item=(ObjectNode)parse(t.getSpecificationSnapshotJson()).path("item").deepCopy();for(String field:List.of("specificationItemId","unitId"))if(item.hasNonNull(field))item.put(field,item.path(field).asText());n.set("specificationSnapshot",item);var results=n.putArray("results");for(var r:db.rows(RESULT,row.getOrgId(),"productionTestInstanceId",row.getId())){var rn=db.view(r);rn.retain("id","orgId","createdBy","createdAt","sampleId","productionTestInstanceId","testCode","revisionNo","previousRevisionId","resultNumeric","resultText","resultConclusion","recordedBy","recordedAt","signatureId");var rv=reviewOf(row.getOrgId(),r.getId());rn.set("review",rv==null?json.nullNode():db.view(rv));if(rn.path("review").isObject())((ObjectNode)rn.path("review")).remove("signatureEvidence");results.add(rn);}if(!frozen){if(t.getStatus().equals("READY"))a.add("RECORD_RESULT");if(t.getStatus().equals("COMPLETED")){if(reviewOf(row.getOrgId(),t.getCurrentResultRevisionId())==null){a.add("REVIEW");a.add("REVISE");}for(var raw:db.rows(DEV,row.getOrgId(),"productionTestInstanceId",t.getId())){var d=(DeviationRow)raw;if("DECIDED".equals(d.getStatus())&&"AUTHORIZE_RETEST".equals(d.getDecisionCode())&&signing.valid(row.getOrgId(),d.getDecisionSignatureId())&&db.rows(TEST,row.getOrgId(),"approvedInvestigationId",d.getId()).size()<d.getAuthorizedRetestCount())a.add("RETEST");}}}}else if(row instanceof DeviationRow d){var capas=n.putArray("capas");for(var r:db.rows(CAPA,row.getOrgId(),"sourceId",row.getId()))capas.add(view(CAPA,r));if(!frozen&&!d.getStatus().equals("CLOSED"))a.add("CREATE_CAPA");if(!frozen)switch(d.getStatus()){case "OPEN"->{a.add("EDIT");a.add("INVESTIGATE");}case "INVESTIGATING"->a.add("DECIDE");case "DECIDED"->a.add("CLOSE");default->{}}}else if(row instanceof CapaRow c){var reviews=n.putArray("reviews");for(var r:db.rows(CAPAREVIEW,row.getOrgId(),"capaId",row.getId())){var rv=db.view(r);rv.remove("signatureEvidence");reviews.add(rv);}if(!frozen)switch(c.getStatus()){case "OPEN"->a.add("START");case "IN_PROGRESS"->a.add("COMPLETE");case "COMPLETED","VERIFIED"->a.add("VERIFY");default->{}}}if(row instanceof DeviationRow)n.retain("id","orgId","createdBy","createdAt","updatedBy","updatedAt","versionNo","allowedActions","deviationNo","investigationScope","mainBatchId","operationExecutionId","investigationKind","severity","status","description","investigationSummary","disposition","decisionCode","productionTestInstanceId","originalResultRevisionId","decisionSignatureId","closeSignatureId","capas");return n;}
 public List<String> envelopes(String type,long org,String target){long id=MasterMutation.id(target.split(":")[0]);var list=new ArrayList<String>();if(type.equals("PRODUCTION_TEST_RESULT"))for(var r:db.rows(RESULT,org,"productionTestInstanceId",id))list.add(((TestResultRevisionRow)r).getSignatureEvidenceJson());else if(type.equals("PRODUCTION_TEST_REVIEW"))for(var r:db.rows(RESULT,org,"productionTestInstanceId",id))for(var v:db.rows(REVIEW,org,"resultRevisionId",r.getId()))list.add(((ProductionTestReviewRow)v).getSignatureEvidenceJson());else if(type.equals("PRODUCTION_DEVIATION")){var d=deviation(org,id);list.add(d.getDecisionSignatureEvidenceJson());list.add(d.getCloseSignatureEvidenceJson());}else for(var r:db.rows(CAPAREVIEW,org,"capaId",id))list.add(((CapaReviewRow)r).getSignatureEvidenceJson());return list;}
 private java.util.List<IncomingRow> sourceRows(String table,long org,String field,Object value){return TransactionSynchronizationManager.isCurrentTransactionReadOnly()?db.rows(table,org,field,value):db.lockedRows(table,org,field,value);}
 /** Full source evidence for archive and canonical digests; excludes computed actions. */
 @Transactional(readOnly=true) public JsonNode sourceEvidence(long org,long batch){batches.batch(org,batch);var n=json.createObjectNode();var samples=n.putArray("samples");var tests=n.putArray("tests");var deviations=n.putArray("deviations");for(var sample:sourceRows(SAMPLE,org,"mainBatchId",batch)){if(!"PRODUCTION".equals(((SampleRow)sample).getSampleScope()))continue;samples.add(db.view(sample));for(var test:sourceRows(TEST,org,"sampleId",sample.getId())){var tn=db.view(test);var results=tn.putArray("results");for(var result:sourceRows(RESULT,org,"productionTestInstanceId",test.getId())){var rn=db.view(result);var reviews=rn.putArray("reviews");for(var review:sourceRows(REVIEW,org,"resultRevisionId",result.getId()))reviews.add(db.view(review));results.add(rn);}tests.add(tn);}}for(var deviation:sourceRows(DEV,org,"mainBatchId",batch)){if(!"PRODUCTION".equals(((DeviationRow)deviation).getInvestigationScope()))continue;var dn=db.view(deviation);var capas=dn.putArray("capas");for(var capa:sourceRows(CAPA,org,"sourceId",deviation.getId())){var cn=db.view(capa);var reviews=cn.putArray("reviews");for(var review:sourceRows(CAPAREVIEW,org,"capaId",capa.getId()))reviews.add(db.view(review));capas.add(cn);}deviations.add(dn);}return n;}}









